import { Component, computed, effect, inject, resource, signal } from '@angular/core';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { firstValueFrom, map } from 'rxjs';
import { TramiteService } from '../../../shared/services/tramite.service';
import { TitleCasePipe } from '@angular/common';
import { extractErrorMessage } from '../../../shared/utils/error-utils';

@Component({
  selector: 'app-asignar-tramites',
  standalone: true,
  imports: [RouterLink, TitleCasePipe],
  templateUrl: './asignar-tramites.component.html',
})
export class AsignarTramitesComponent {
  private route = inject(ActivatedRoute);
  private router = inject(Router);
  private tramiteService = inject(TramiteService);
  readonly folio = this.route.snapshot.paramMap.get('id') ?? '—';
  readonly folioSignal = signal(this.folio);

  readonly allTramitesResource = resource({
    loader: () => {
      return firstValueFrom(
        this.tramiteService.getTramites({ page: 1, perPage: 100 }).pipe(
          map(res => res.data)
        )
      );
    }
  });

  readonly allTramites = computed(() => {
    if (this.allTramitesResource.error()) {
      return [];
    }
    return this.allTramitesResource.value() ?? [];
  });
  readonly assignedTramites = computed(() => {
    if (this.assignedTramitesResource.error()) {
      return [];
    }
    return this.assignedTramitesResource.value() ?? [];
  });

  readonly assignedTramitesResource = resource({
    params: () => ({ folio: this.folioSignal() }),
    loader: ({ params }) => firstValueFrom(this.tramiteService.getTramitesAsignados(params.folio))
  });

  selectedTramiteIds = signal<Set<number>>(new Set());
  readonly error = signal<string | null>(null);

  readonly cambiosResumen = computed(() => {
    const seleccionados = this.selectedTramiteIds();
    const asignados = this.assignedTramites().map(t => t.tramite_id);
    const aAgregar = [...seleccionados].filter(id => !asignados.includes(id));
    const aQuitar = asignados.filter(id => !seleccionados.has(id));
    return { agregar: aAgregar.length, quitar: aQuitar.length };
  });

  readonly isTramiteAsignado = (id: number): boolean =>
    this.assignedTramites().some(t => t.tramite_id === id);

  private seeded = false;

  constructor() {
    effect(() => {
      const assigned = this.assignedTramitesResource.value();
      if (assigned && !this.seeded) {
        this.seeded = true;
        this.selectedTramiteIds.set(new Set(assigned.map(t => t.tramite_id)));
      }
    });
  }

  isTramiteSelected(id: number): boolean {
    return this.selectedTramiteIds().has(id);
  }

  toggleTramite(id: number): void {
    this.selectedTramiteIds.update(current => {
      const next = new Set(current);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  }

  readonly mostrarModalConfirmacion = signal(false);

  onGuardar(): void {
    this.mostrarModalConfirmacion.set(true);
  }

  cerrarModalConfirmacion(): void {
    this.mostrarModalConfirmacion.set(false);
  }

  cerrarModalConBackdrop(event: MouseEvent): void {
    if (event.target === event.currentTarget) {
      this.cerrarModalConfirmacion();
    }
  }

  confirmarGuardado(): void {
    this.mostrarModalConfirmacion.set(false);

    const ids = Array.from(this.selectedTramiteIds());
    this.tramiteService.asignarTramites(this.folio, ids).subscribe({
      next: () => {
        this.router.navigate(['/ejecutivos/autorizadas', this.folio, 'revision']);
      },
      error: (err) => {
        this.error.set(extractErrorMessage(err));
      },
    });
  }
}
